/**
 * The loader of streamed recordings as it runs in a Worker: `createRecordingLoader`
 * over the origin private file system. It is not imported by the package:
 * `bun run worklet:build` bundles it into `RECORDING_LOADER_WORKER`, the
 * source a page starts the worker from.
 */
import { createRecordingLoader, type RecordingFile } from "./loader";
import type {
  RecordingLoaderMessage,
  RecordingLoaderReply,
} from "./protocol";

/** The file handle a worker can open for synchronous access, which the DOM library leaves out. */
interface SyncFileHandle extends FileSystemFileHandle {
  createSyncAccessHandle: () => Promise<RecordingFile>;
}

const scope = globalThis as unknown as {
  onmessage: ((event: MessageEvent<RecordingLoaderMessage>) => void) | null;
  postMessage: (message: RecordingLoaderReply) => void;
};

const handle = createRecordingLoader({
  open: async (path) => {
    const folder = await path
      .slice(0, -1)
      .reduce<Promise<FileSystemDirectoryHandle>>(
        async (parent, name) => (await parent).getDirectoryHandle(name),
        navigator.storage.getDirectory()
      );
    const file = (await folder.getFileHandle(
      path.at(-1) ?? ""
    )) as SyncFileHandle;
    return file.createSyncAccessHandle();
  },
  reply: (message) => scope.postMessage(message),
});

scope.onmessage = (event) => {
  handle(event.data);
};

import type {
  RecordingLoaderMessage,
  RecordingLoaderReply,
} from "./protocol";
import { PageCache } from "./stream";

/** What the loader reads a recording's file through: a synchronous access handle of the origin private file system. */
export interface RecordingFile {
  close: () => void;
  read: (buffer: Float32Array, options: { at: number }) => number;
}

/**
 * The loader of streamed recordings, with no worker around it: it opens each
 * recording's file with `open`, loads the pages asked for into the pool its
 * streams share, and answers through `reply`. Messages are handled one after
 * the other, in the order they came, so a request never runs ahead of the
 * file it needs.
 */
export function createRecordingLoader({
  open,
  reply,
}: {
  open: (path: readonly string[]) => Promise<RecordingFile>;
  reply: (message: RecordingLoaderReply) => void;
}): (message: RecordingLoaderMessage) => Promise<void> {
  const files = new Map<string, { file: RecordingFile; length: number }>();
  let cache: PageCache | null = null;
  let queue: Promise<void> = Promise.resolve();

  const readPage = (
    id: string,
    page: number,
    channels: readonly Float32Array[]
  ) => {
    const held = files.get(id);
    const [first] = channels;
    if (!(held && first)) {
      return;
    }
    const start = page * first.length;
    const frames = Math.min(first.length, held.length - start);
    for (const [channel, view] of channels.entries()) {
      held.file.read(view.subarray(0, frames), {
        at: (channel * held.length + start) * Float32Array.BYTES_PER_ELEMENT,
      });
    }
  };

  const receive = async (message: RecordingLoaderMessage) => {
    if (message.type === "add") {
      try {
        const file = await open(message.path);
        files.set(message.id, { file, length: message.stream.length });
        cache ??= new PageCache(message.stream.pool, readPage);
        cache.add(message.id, message.stream);
      } catch (error) {
        reply({ id: message.id, message: String(error), type: "failed" });
      }
    } else if (message.type === "forget") {
      cache?.forget(message.id);
      files.get(message.id)?.file.close();
      files.delete(message.id);
    } else {
      reply({
        id: message.id,
        loaded: cache ? cache.want(message.requests) : 0,
        type: "loaded",
      });
    }
  };

  return (message) => {
    queue = queue.then(() => receive(message));
    return queue;
  };
}

/**
 * The mixer's arithmetic: how a pan sets two gains, which tracks a solo lets
 * through, and how long each path waits so that every one reaches the main
 * track at the same frame. No audio in it: a host's engine applies it.
 */

/**
 * The gains of the left and right channels for a pan from -1 (left) to 1
 * (right): a constant-power law on sine curves, with both channels at unity
 * in the centre and the side it is turned to at +3 dB at either end. Each
 * channel has its own gain, so nothing of one moves into the other.
 */
export function panGains(pan: number): readonly [left: number, right: number] {
  const clamped = Number.isFinite(pan) ? Math.max(-1, Math.min(1, pan)) : 0;
  const angle = ((clamped + 1) * Math.PI) / 4;
  return [Math.SQRT2 * Math.cos(angle), Math.SQRT2 * Math.sin(angle)];
}

/** A track as the solo sees it. */
export interface SoloTrack {
  /** The group track it plays into, if any: a group is heard while a track in it is soloed, and a soloed group lets its tracks be heard. */
  group?: string | null;
  id: string;
  /** A return track carries what the others send it. */
  kind: "return" | "track";
  soloed: boolean;
}

/** What a solo lets through: each track's own output, and each of its sends. */
export interface SoloState {
  /** Whether a track's output (to the main track) is heard. */
  heard: (track: string) => boolean;
  /** Whether a track's send to a return passes. */
  sends: (track: string, to: string) => boolean;
}

/**
 * The tracks a solo lets through, once groups are counted: the soloed ones,
 * the groups each sits in (which carry its sound), and the tracks of a soloed
 * group.
 */
function withGroups(
  tracks: readonly SoloTrack[],
  soloed: ReadonlySet<string>
): Set<string> {
  const groupOf = new Map(
    tracks.map((track) => [track.id, track.group ?? null])
  );
  const ancestors = (id: string) => {
    const found: string[] = [];
    let at = groupOf.get(id) ?? null;
    while (at !== null && !found.includes(at)) {
      found.push(at);
      at = groupOf.get(at) ?? null;
    }
    return found;
  };
  const heard = new Set<string>();
  for (const track of tracks) {
    const up = ancestors(track.id);
    if (soloed.has(track.id) || up.some((group) => soloed.has(group))) {
      heard.add(track.id);
      for (const group of up) {
        heard.add(group);
      }
    }
  }
  return heard;
}

/**
 * Which tracks a solo silences. Nothing soloed, everything plays. Soloed
 * tracks are heard and every other track is silenced, its sends with it; the
 * return tracks stay heard when `inPlace` is on, so a soloed track keeps its
 * reverb. A soloed return is heard with what the others send it, while their
 * own outputs are silenced. The main track is not a track here: it is always
 * heard.
 */
export function soloState(
  tracks: readonly SoloTrack[],
  { inPlace = true }: { inPlace?: boolean } = {}
): SoloState {
  const soloedTracks = withGroups(
    tracks.filter((track) => track.kind === "track"),
    new Set(
      tracks
        .filter((track) => track.soloed && track.kind === "track")
        .map((track) => track.id)
    )
  );
  const soloedReturns = new Set(
    tracks
      .filter((track) => track.soloed && track.kind === "return")
      .map((track) => track.id)
  );
  const returns = new Set(
    tracks.filter((track) => track.kind === "return").map((track) => track.id)
  );
  const any =
    tracks.some((track) => track.soloed && track.kind === "track") ||
    soloedReturns.size > 0;
  return {
    heard: (track) => {
      if (!any) {
        return true;
      }
      if (returns.has(track)) {
        return (
          soloedReturns.has(track) ||
          (inPlace && soloedReturns.size === 0 && soloedTracks.size > 0)
        );
      }
      return soloedTracks.has(track);
    },
    sends: (track, to) =>
      !any || soloedTracks.has(track) || soloedReturns.has(to),
  };
}

/** A path into the mixer as delay compensation sees it: how many frames its devices delay it. */
export interface DelayedTrack {
  id: string;
  /** The frames its device chain delays it. */
  latency: number;
}

/** How long each path waits, in frames, so that all of them line up at the main track. */
export interface Compensation {
  /** What waits after each return's chain. */
  returns: ReadonlyMap<string, number>;
  /** The frames the whole mix comes out late: the slowest track's chain, then the slowest return's. */
  total: number;
  /** What waits after each track's chain (its sends tap after it), and then on its way to the main track alone. */
  tracks: ReadonlyMap<string, { chain: number; main: number }>;
}

/**
 * The waits that line every path up at the main track. Each track waits after
 * its chain for the slowest track's chain, so all their outputs and all their
 * sends leave in step; each return waits after its chain for the slowest
 * return's; and a track's own output then waits that long again, so it meets
 * the returns at the main track. Latencies that are not whole positive
 * frames count as none.
 */
export function delayCompensation(
  tracks: readonly DelayedTrack[],
  returns: readonly DelayedTrack[]
): Compensation {
  const frames = (latency: number) =>
    Number.isFinite(latency) && latency > 0 ? Math.round(latency) : 0;
  const slowestTrack = Math.max(
    0,
    ...tracks.map((track) => frames(track.latency))
  );
  const slowestReturn = Math.max(
    0,
    ...returns.map((track) => frames(track.latency))
  );
  return {
    returns: new Map(
      returns.map((track) => [track.id, slowestReturn - frames(track.latency)])
    ),
    total: slowestTrack + slowestReturn,
    tracks: new Map(
      tracks.map((track) => [
        track.id,
        { chain: slowestTrack - frames(track.latency), main: slowestReturn },
      ])
    ),
  };
}

/** A path into the mixer as routing sees it: its delay, where it plays into, and the returns it sends to. */
export interface RoutedTrack extends DelayedTrack {
  /** The group track it plays into; none, or one that is not a track, is the main track. */
  group?: string | null;
  /** The return tracks it sends to. */
  sends?: readonly string[];
}

/** How long each path waits, in frames, so that everything meeting anywhere meets on the same frame. */
export interface RoutedCompensation {
  /** What waits on the way from each track, group and return to where it plays into. */
  out: ReadonlyMap<string, number>;
  /** What waits on each send, by the track that sends, then the return it reaches. */
  sends: ReadonlyMap<string, ReadonlyMap<string, number>>;
  /** The frames the whole mix comes out late. */
  total: number;
}

/**
 * The waits that line every path up wherever paths meet: at a group, the
 * sound of each of its tracks; at a return, each send; at the main track, the
 * top tracks and groups and the returns. A path is ready when its sound has
 * come through its own chain after everything that plays into it; each that
 * is ready sooner than the slowest waits the difference on its way. Groups
 * can hold groups; a group that would hold itself counts as playing into the
 * main track. Latencies that are not whole positive frames count as none.
 */
export function routedCompensation(
  tracks: readonly RoutedTrack[],
  returns: readonly DelayedTrack[]
): RoutedCompensation {
  const frames = (latency: number) =>
    Number.isFinite(latency) && latency > 0 ? Math.round(latency) : 0;
  const byId = new Map(tracks.map((track) => [track.id, track]));
  const parentOf = (track: RoutedTrack) => {
    const group = track.group ?? null;
    return group !== null && group !== track.id && byId.has(group)
      ? group
      : null;
  };
  const children = new Map<string, RoutedTrack[]>();
  for (const track of tracks) {
    const parent = parentOf(track);
    if (parent !== null) {
      children.set(parent, [...(children.get(parent) ?? []), track]);
    }
  }
  const ready = new Map<string, number>();
  const readyOf = (track: RoutedTrack, seen: ReadonlySet<string>): number => {
    const known = ready.get(track.id);
    if (known !== undefined) {
      return known;
    }
    const inner = (children.get(track.id) ?? []).filter(
      (child) => !seen.has(child.id)
    );
    const next = new Set([...seen, track.id]);
    const arrives = Math.max(0, ...inner.map((child) => readyOf(child, next)));
    const done = arrives + frames(track.latency);
    ready.set(track.id, done);
    return done;
  };
  for (const track of tracks) {
    readyOf(track, new Set());
  }
  const out = new Map<string, number>();
  const sends = new Map<string, Map<string, number>>();
  for (const track of tracks) {
    const parent = parentOf(track);
    if (parent !== null) {
      const arrives =
        (ready.get(parent) ?? 0) - frames(byId.get(parent)?.latency ?? 0);
      out.set(track.id, arrives - (ready.get(track.id) ?? 0));
    }
  }
  const returnReady = new Map<string, number>();
  for (const back of returns) {
    const senders = tracks.filter((track) => track.sends?.includes(back.id));
    const arrives = Math.max(
      0,
      ...senders.map((track) => ready.get(track.id) ?? 0)
    );
    for (const sender of senders) {
      const waits = sends.get(sender.id) ?? new Map<string, number>();
      waits.set(back.id, arrives - (ready.get(sender.id) ?? 0));
      sends.set(sender.id, waits);
    }
    returnReady.set(back.id, arrives + frames(back.latency));
  }
  const top = tracks.filter((track) => parentOf(track) === null);
  const total = Math.max(
    0,
    ...top.map((track) => ready.get(track.id) ?? 0),
    ...returnReady.values()
  );
  for (const track of top) {
    out.set(track.id, total - (ready.get(track.id) ?? 0));
  }
  for (const [id, done] of returnReady) {
    out.set(id, total - done);
  }
  return { out, sends, total };
}

/** A note's id: unique within its clip. */
export type NoteId = number | string;

/** A note of a MIDI clip: its pitch, start and length, how hard and how likely it plays, how far its velocity may stray, and whether it is deactivated. */
export interface Note {
  /** How likely the note is to play each time it comes round, 0 to 1. @default 1 */
  chance?: number;
  /** How far the velocity may stray each time the note plays, as a share of the full range. @default 0 */
  deviation?: number;
  id: NoteId;
  /** Length, in the clip's units. */
  length: number;
  /** Whether the note is deactivated: it stays in the clip, and does not play. @default false */
  muted?: boolean;
  /** MIDI pitch: 60 is middle C. */
  pitch: number;
  /** Where the note starts, in the clip's units. */
  start: number;
  /** How hard the note is played, 0 to 1. @default 1 */
  velocity?: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(value, max));

/**
 * How hard a note plays this time round, from 0 to 1, or `null` when it does
 * not: a deactivated note never plays, one with a `chance` plays that share of
 * the times, and a `deviation` strays its velocity by up to that much, a new
 * roll each time. `random` gives numbers from 0 to 1: `Math.random` unless a
 * test or a seeded render passes its own.
 */
export function playedVelocity(
  note: Pick<Note, "chance" | "deviation" | "muted" | "velocity">,
  random: () => number = Math.random
): number | null {
  if (note.muted || random() >= (note.chance ?? 1)) {
    return null;
  }
  return clamp((note.velocity ?? 1) + random() * (note.deviation ?? 0), 0, 1);
}

import type { PlayedClip } from "./clip";
import { sourceIndexer } from "./render";
import type { PageRequest } from "./stream";
import { type PlaybackState, playbackRuns } from "./transport";

/**
 * How finely a clip's reading is followed: eight times a page, so no page is
 * skipped where a warp reads its recording up to eight times faster than it
 * was recorded.
 */
const STEPS_PER_PAGE = 8;

/** What the planner needs of a recording: its rate and its length in frames. */
export interface PlannedRecording {
  length: number;
  sampleRate: number;
}

/**
 * The pages a track's clips read over the `count` frames of the audio clock
 * from `frame`, the soonest read first: what a loader should have in the pool
 * before then. Stopped, it plans as if playback started from the state's
 * position at `frame`, so the place a play would start from is ready. Each
 * read takes the pages of the frames around it too, which an interpolated
 * read touches.
 */
export function pagesAhead(
  state: PlaybackState,
  clips: readonly PlayedClip[],
  frame: number,
  count: number,
  recordings: (id: string) => PlannedRecording | undefined,
  sampleRate: number,
  pageFrames: number
): PageRequest[] {
  const playing = state.playing
    ? state
    : { ...state, at: frame, playing: true };
  const first = new Map<string, { at: number; request: PageRequest }>();
  const add = (
    recording: string,
    length: number,
    source: number,
    at: number
  ) => {
    if (Number.isNaN(source)) {
      return;
    }
    const index = Math.floor(source);
    for (const read of [index - 1, index + 2]) {
      if (read >= 0 && read < length) {
        const page = Math.floor(read / pageFrames);
        const key = `${recording}\u0000${page}`;
        if (!first.has(key)) {
          first.set(key, { at, request: { page, recording } });
        }
      }
    }
  };
  const step = Math.max(1, Math.floor(pageFrames / STEPS_PER_PAGE));
  for (const run of playbackRuns(playing, frame, count)) {
    const runEnd = run.position + run.length;
    for (const clip of clips) {
      const from = Math.max(run.position, clip.start);
      const to = Math.min(runEnd, clip.end);
      const recording = recordings(clip.recording);
      if (from >= to || !recording) {
        continue;
      }
      const sourceAt = sourceIndexer(clip, recording.sampleRate, sampleRate);
      const clockOf = (position: number) =>
        frame + run.offset + position - run.position;
      for (let position = from; position < to; position += step) {
        add(
          clip.recording,
          recording.length,
          sourceAt(position),
          clockOf(position)
        );
      }
      add(clip.recording, recording.length, sourceAt(to - 1), clockOf(to - 1));
    }
  }
  return [...first.values()]
    .sort((a, b) => a.at - b.at)
    .map((entry) => entry.request);
}

import type { PlayedClip } from "./clip";
import type { PageRequest, RecordingStream } from "./stream";
import type { PlaybackState } from "./transport";

/** The name the clip player's processor is registered under in an AudioWorklet. */
export const CLIP_PLAYER_PROCESSOR = "audioui-clip-player";

/**
 * What the main thread posts to a clip player's port. The recordings are kept
 * once for the whole context: every player of the context reads them, so a
 * recording posted through one player is there for all of them.
 */
export type ClipPlayerMessage =
  /** Keeps a decoded recording under `id`, for every player of the context. */
  | {
      channels: Float32Array[];
      id: string;
      sampleRate: number;
      type: "recording";
    }
  /** Keeps a streamed recording under `id`, read from the pages of its stream, for every player of the context. */
  | {
      id: string;
      sampleRate: number;
      stream: RecordingStream;
      type: "stream";
    }
  /** Lets a recording go. */
  | { id: string; type: "forget" }
  /** The track's clips, from the next block on. */
  | { clips: PlayedClip[]; type: "clips" }
  /** A state of the transport, taken over at its frame. */
  | { state: PlaybackState; type: "state" }
  /** Asks the processor to answer `synced` with the same id once it has every message before this one. */
  | { id: number; type: "sync" }
  /** Ends the player: its processor stops being called. */
  | { type: "dispose" };

/** What a clip player's processor posts back. */
export type ClipPlayerReply = { id: number; type: "synced" };

/**
 * What the main thread posts to the loader of streamed recordings, a Worker.
 * A recording's file, in the origin private file system, holds its channels
 * one after the other, each its frames as 32-bit floats at the engine's rate.
 */
export type RecordingLoaderMessage =
  /** Opens a recording's file, at `path` from the root of the origin private file system, and loads its pages into `stream`. */
  | {
      id: string;
      path: readonly string[];
      stream: RecordingStream;
      type: "add";
    }
  /** Lets a recording go: its file is closed and its slots are free. */
  | { id: string; type: "forget" }
  /** Loads the pages asked for that are missing, soonest first; answered with `loaded` and the same id. */
  | { id: number; requests: readonly PageRequest[]; type: "want" };

/** What the loader posts back. */
export type RecordingLoaderReply =
  | { id: number; loaded: number; type: "loaded" }
  /** A recording's file could not be opened: its pages stay silent. */
  | { id: string; message: string; type: "failed" };

import {
  createWarpReader,
  fadeGain,
  type PlayedClip,
  type PlayedStretch,
} from "./clip";
import { type RecordingStream, slotOffset, streamedSample } from "./stream";
import {
  continuesFrom,
  type PlaybackState,
  playbackRuns,
  STOPPED,
} from "./transport";

/** A recording held in memory, decoded: one array of samples per channel. */
export interface DecodedRecording {
  readonly channels: readonly Float32Array[];
  readonly sampleRate: number;
}

/** A recording read from the pages of a stream, which something else keeps filled ahead of playback. */
export interface StreamedRecording {
  readonly sampleRate: number;
  readonly stream: RecordingStream;
}

/** A recording a clip plays: decoded in memory, or streamed. */
export type Recording = DecodedRecording | StreamedRecording;

/** A streamed channel's sample at an index of the recording, fractional when it is interpolated. */
type Sampler = (source: number) => number;

/** The recordings a player can read, by id. */
export type Recordings = ReadonlyMap<string, Recording>;

/** How long a stop or a jump fades the sound out, and the sound after a jump in. */
export const DECLICK_SECONDS = 0.002;

/** The 4-point cubic (Catmull-Rom) through four samples, at `t` between the middle two. */
function cubic(y0: number, y1: number, y2: number, y3: number, t: number) {
  const c1 = 0.5 * (y2 - y0);
  const c2 = y0 - 2.5 * y1 + 2 * y2 - 0.5 * y3;
  const c3 = 0.5 * (y3 - y0) + 1.5 * (y1 - y2);
  return ((c3 * t + c2) * t + c1) * t + y1;
}

/** A sample at a fractional index, through the cubic; outside the recording it is silence. */
function interpolate(data: Float32Array, at: number): number {
  const index = Math.floor(at);
  return cubic(
    data[index - 1] ?? 0,
    data[index] ?? 0,
    data[index + 1] ?? 0,
    data[index + 2] ?? 0,
    at - index
  );
}

/** How each channel of a stream is sampled, a mono one in both: a copy of the frame when `exact`, the cubic otherwise. */
function streamSamplers(
  stream: RecordingStream,
  exact: boolean
): readonly [Sampler, Sampler] {
  const { pageFrames, samples } = stream.pool;
  const of = (channel: number): Sampler => {
    const read = (index: number) => streamedSample(stream, channel, index);
    return exact
      ? read
      : (at) => {
          const index = Math.floor(at);
          const page = Math.floor((index - 1) / pageFrames);
          const slot = stream.directory[page] ?? -1;
          // The four points on one page, as they nearly always are: found once.
          if (
            slot >= 0 &&
            index - 1 >= 0 &&
            index + 2 < stream.length &&
            Math.floor((index + 2) / pageFrames) === page
          ) {
            const base =
              slotOffset(stream.pool, slot, channel) +
              index -
              page * pageFrames;
            return cubic(
              samples[base - 1] as number,
              samples[base] as number,
              samples[base + 1] as number,
              samples[base + 2] as number,
              at - index
            );
          }
          return cubic(
            read(index - 1),
            read(index),
            read(index + 1),
            read(index + 2),
            at - index
          );
        };
  };
  return [of(0), of(stream.channels > 1 ? 1 : 0)];
}

/** The clip's own frame at the arrangement's frame `frame`, folded into its loop once it passes the loop's end. */
function ownFrame(clip: PlayedClip, frame: number): number {
  const own = frame + clip.shift;
  const { loop } = clip;
  if (!loop || own < loop[1]) {
    return own;
  }
  return loop[0] + ((own - loop[0]) % (loop[1] - loop[0]));
}

/** The clip's gain at the arrangement's frame `frame`: its gain, through its fades. */
function gainAt(clip: PlayedClip, frame: number): number {
  let { gain } = clip;
  const fromStart = frame - clip.start;
  if (fromStart < clip.fadeIn) {
    gain *= fadeGain(clip.fadeInShape, fromStart / clip.fadeIn);
  }
  const toEnd = clip.end - frame;
  if (toEnd <= clip.fadeOut) {
    gain *= fadeGain(clip.fadeOutShape, toEnd / clip.fadeOut);
  }
  return gain;
}

/**
 * Where in the recording the clip reads its own frame `read`, in frames of the
 * recording: a whole frame at speed 1 on the engine's sample rate, a
 * fractional one when it is warped or the recording is at another rate.
 */
function locator(
  clip: PlayedClip,
  rate: number,
  sampleRate: number
): (read: number) => number {
  if (clip.warp === null && rate === sampleRate) {
    const first = Math.round(clip.sourceFrom * rate);
    return (read) => first + read;
  }
  const unwarp = clip.warp ? createWarpReader(clip.warp) : null;
  const first = clip.sourceFrom * rate;
  return (read) =>
    first + (unwarp ? unwarp(read / sampleRate) : read / sampleRate) * rate;
}

/**
 * Where in its recording `clip` reads at the arrangement's frame `frame`, in
 * frames of the recording (fractional when warped or at another rate), or
 * NaN where it plays nothing: what both the player and the planner of a
 * stream's pages follow. `rate` is the recording's sample rate. A clip that
 * stretches time reads its grain's own stretch.
 */
export function sourceIndexer(
  clip: PlayedClip,
  rate: number,
  sampleRate: number
): (frame: number) => number {
  const locate = locator(clip, rate, sampleRate);
  const { stretch } = clip;
  const step = stretch ? (stretch.speed * rate) / sampleRate : 0;
  return (frame) => {
    const own = ownFrame(clip, frame);
    const read = clip.reversed ? clip.span - 1 - own : own;
    if (!(read >= 0 && read < clip.span)) {
      return Number.NaN;
    }
    if (!stretch) {
      return locate(read);
    }
    const start = Math.floor(read / stretch.hop) * stretch.hop;
    return locate(start) + (read - start) * step;
  };
}

/** How far each way a grain of Tones may move to line up on the last, in seconds: a period of a note down to about 83 Hz. */
const ALIGN_SECONDS = 0.006;
/** How finely it first looks, then looks again around the best, in frames of the recording. */
const COARSE_STEP = 4;
const FINE_REACH = 3;
/** How many points of the sound it compares: what keeps it far inside a render quantum. */
const COMPARE_POINTS = 60;
/** What the grain before reads, kept here so it is read once and nothing is allocated. */
const comparing = new Float32Array(COMPARE_POINTS);

/** Where each of a clip's grains of Tones was moved to line up on the last, in frames of the recording. */
interface Alignment {
  /** The last grain worked out. */
  last: number;
  moved: Float32Array;
}

const alignments = new WeakMap<PlayedClip, Alignment>();

/** Where in its grain each clip works the next one out, as a share of it: spread apart, so clips that start together do not all do it in one block. It changes when the work is done, never what comes out. */
const lookAheadShares = new WeakMap<PlayedClip, number>();
let clipsLookingAhead = 0;
const GOLDEN_SHARE = 0.618_033_988_75;

function lookAheadShare(clip: PlayedClip): number {
  let share = lookAheadShares.get(clip);
  if (share === undefined) {
    clipsLookingAhead += 1;
    share = (clipsLookingAhead * GOLDEN_SHARE) % 1;
    lookAheadShares.set(clip, share);
  }
  return share;
}

/**
 * How far the grain `index` of `clip` moves to line up on the one before it:
 * where what they share matches best, read on whole frames (close enough to
 * line up on, and a quarter of the reads), worked out once, from the grain before
 * it. A jump starts the chain again there, unmoved.
 */
function alignedAt(
  clip: PlayedClip,
  stretch: PlayedStretch,
  index: number,
  locate: (read: number) => number,
  nearest: Sampler,
  step: number,
  rate: number
): number {
  let alignment = alignments.get(clip);
  if (!alignment) {
    alignment = {
      last: -1,
      moved: new Float32Array(Math.ceil(clip.span / stretch.hop) + 2),
    };
    alignments.set(clip, alignment);
  }
  const { moved } = alignment;
  if (index <= alignment.last) {
    return moved[index] ?? 0;
  }
  if (index > alignment.last + 1) {
    // Played from here: the chain starts again.
    moved[index] = 0;
    alignment.last = index;
    return 0;
  }
  const reach = Math.round(ALIGN_SECONDS * rate);
  const before = (moved[index - 1] ?? 0) + locate((index - 1) * stretch.hop);
  const here = locate(index * stretch.hop);
  const { hop } = stretch;
  const spacing = hop / COMPARE_POINTS;
  // They share the stretch before this grain's start, where it crosses in.
  for (let point = 0; point < COMPARE_POINTS; point += 1) {
    comparing[point] = nearest(before + point * spacing * step);
  }
  const score = (shift: number) => {
    let sum = 0;
    for (let point = 0; point < COMPARE_POINTS; point += 1) {
      sum +=
        (comparing[point] as number) *
        nearest(here + shift + (point * spacing - hop) * step);
    }
    return sum;
  };
  let best = 0;
  let bestScore = score(0);
  const look = (from: number, to: number, by: number) => {
    for (let shift = from; shift <= to; shift += by) {
      const value = score(shift);
      if (value > bestScore) {
        bestScore = value;
        best = shift;
      }
    }
  };
  look(-reach, reach, COARSE_STEP);
  look(best - FINE_REACH, best + FINE_REACH, 1);
  moved[index] = best;
  alignment.last = index;
  return best;
}

/**
 * Adds what a clip that stretches time plays over `length` frames from
 * `position`: its grains, each from where the warp places its start at its own
 * speed. The next grain crosses in before its start, so it is at full level
 * from there on: an attack on a slice's start keeps its shape.
 */
function renderStretchedClip(
  output: readonly Float32Array[],
  at: number,
  length: number,
  position: number,
  clip: PlayedClip,
  stretch: PlayedStretch,
  left: Sampler,
  right: Sampler,
  nearest: Sampler,
  rate: number,
  sampleRate: number
) {
  const from = Math.max(position, clip.start);
  const to = Math.min(position + length, clip.end);
  const [outLeft, outRight] = output;
  if (from >= to || !outLeft) {
    return;
  }
  const locate = locator(clip, rate, sampleRate);
  const { fade, hop } = stretch;
  const step = (stretch.speed * rate) / sampleRate;
  const startOf = (index: number) =>
    locate(index * hop) +
    (stretch.aligned
      ? alignedAt(clip, stretch, index, locate, nearest, step, rate)
      : 0);
  const aheadAt = stretch.aligned
    ? lookAheadShare(clip) * hop
    : Number.POSITIVE_INFINITY;
  const add = (out: number, l: number, r: number, gain: number) => {
    outLeft[out] = (outLeft[out] as number) + l * gain;
    if (outRight) {
      outRight[out] = (outRight[out] as number) + r * gain;
    }
  };
  let grain = -1;
  let start = 0;
  let next = 0;
  let ahead = -1;
  for (let frame = from; frame < to; frame += 1) {
    const own = ownFrame(clip, frame);
    const read = clip.reversed ? clip.span - 1 - own : own;
    if (read >= 0 && read < clip.span) {
      const index = Math.floor(read / hop);
      if (index !== grain) {
        grain = index;
        start = startOf(index);
        next = startOf(index + 1);
      }
      const into = read - index * hop;
      if (into >= aheadAt && ahead !== index) {
        ahead = index;
        startOf(index + 2);
      }
      const here = start + into * step;
      let l = left(here);
      let r = right(here);
      const crossing = into - (hop - fade);
      if (crossing >= 0) {
        const rise = crossing / fade;
        const coming = next + (into - hop) * step;
        l = l * (1 - rise) + left(coming) * rise;
        r = r * (1 - rise) + right(coming) * rise;
      }
      add(at + frame - position, l, r, gainAt(clip, frame));
    }
  }
}

/**
 * Adds what `clip` plays over `length` frames of the arrangement from
 * `position` into `output` from index `at`. At speed 1, on the engine's
 * sample rate, it copies the recording's frames as they are; warped, or from
 * a recording at another rate, it reads them through the interpolator.
 */
function renderClip(
  output: readonly Float32Array[],
  at: number,
  length: number,
  position: number,
  clip: PlayedClip,
  recording: Recording,
  sampleRate: number
) {
  if ("stream" in recording) {
    renderStreamedClip(
      output,
      at,
      length,
      position,
      clip,
      recording,
      sampleRate
    );
    return;
  }
  const from = Math.max(position, clip.start);
  const to = Math.min(position + length, clip.end);
  const [left, right = left] = recording.channels;
  const [outLeft, outRight] = output;
  if (from >= to || !left || !right || !outLeft) {
    return;
  }
  if (clip.stretch) {
    renderStretchedClip(
      output,
      at,
      length,
      position,
      clip,
      clip.stretch,
      (source) => interpolate(left, source),
      (source) => interpolate(right, source),
      (source) => left[Math.round(source)] ?? 0,
      recording.sampleRate,
      sampleRate
    );
    return;
  }
  // The loop of every block, kept as plain array reads: the fast path.
  const exact = clip.warp === null && recording.sampleRate === sampleRate;
  const sample = (data: Float32Array, source: number) =>
    exact ? (data[source] ?? 0) : interpolate(data, source);
  const locate = locator(clip, recording.sampleRate, sampleRate);
  for (let frame = from; frame < to; frame += 1) {
    const own = ownFrame(clip, frame);
    const read = clip.reversed ? clip.span - 1 - own : own;
    if (read >= 0 && read < clip.span) {
      const index = at + frame - position;
      const gain = gainAt(clip, frame);
      const source = locate(read);
      outLeft[index] = (outLeft[index] as number) + sample(left, source) * gain;
      if (outRight) {
        outRight[index] =
          (outRight[index] as number) + sample(right, source) * gain;
      }
    }
  }
}

/** What `renderClip` does for a recording read through the pages of its stream. */
function renderStreamedClip(
  output: readonly Float32Array[],
  at: number,
  length: number,
  position: number,
  clip: PlayedClip,
  recording: StreamedRecording,
  sampleRate: number
) {
  const from = Math.max(position, clip.start);
  const to = Math.min(position + length, clip.end);
  const [outLeft, outRight] = output;
  if (from >= to || !outLeft) {
    return;
  }
  const exact =
